int update_pit_state(struct kvm *kvm, struct kvm_pit_state2 *ps) {
    int ret = 0;

    if (!kvm || !ps) {
        return -1;
    }

    mutex_lock(&kvm->pit_state_mutex);

    kvm->pit.flags &= ~KVM_PIT_FLAGS_HPET_LEGACY;
    kvm->pit.flags |= ps->flags & KVM_PIT_FLAGS_HPET_LEGACY;

    memcpy(&kvm->pit.channels[0], &ps->channels[0], sizeof(ps->channels));

    kvm->pit.flags |= KVM_PIT_FLAGS_UPDATED;

    kvm_pit_load_count_state(kvm);

    mutex_unlock(&kvm->pit_state_mutex);

    return ret;
}
